    const cols = line.split(line.includes(';') ? ';' : ',');
    const file = (cols[0] || '').trim();
    const voto = Number((cols[1] || '').trim());
    if (file && voto >= 1 && voto <= 5) votes[file] = { voto, nota: (cols[2] || '').trim() };
  }
  return votes;
}

