// ---- Identita' dei generi: stile composto in codice, varianti scelte con UCB sui voti ----

// Statistiche per variante di un genere (voti utente e dati automatici)
function varianteStats(tracks, votes, nomeCategoria) {
  const stats = {};
  for (const t of tracks) {
    if (t.meta.categoria !== nomeCategoria || !t.meta.variante) continue;
    const s = (stats[t.meta.variante] = stats[t.meta.variante] || { nu: 0, u: 0, na: 0, a: 0 });
    s.na++;
    if (t.meta.qualita && t.meta.qualita.esito === 'ok') s.a++;
    const v = votoUtente(t, votes);
    if (v) { s.nu++; s.u += (v - 1) / 4; }
  }
  return stats;
}

// Sceglie la variante del genere con il punteggio migliore (UCB), con un po' di esplorazione
function pickVariante(cat, tracks, votes) {
  const varianti = cat.varianti || [];
  if (!varianti.length) return null;
  const stats = varianteStats(tracks, votes, cat.name);
  const totale = tracks.filter((t) => t.meta.categoria === cat.name).length;
  const scelte = varianti.map((v) => ({ v, ...ricettaScore(stats[v.nome], totale) }));
  scelte.sort((a, b) => b.score - a.score);
  return scelte[0].v;
}

// Sottoinsieme casuale di strumenti del genere (solo quelli del suo set), 2-4 per brano
function scegliStrumenti(cat) {
  const pool = [...(cat.strumenti || [])];
  const n = Math.min(pool.length, 2 + Math.floor(Math.random() * 3));
  const scelti = [];
  while (scelti.length < n && pool.length) scelti.push(pool.splice(Math.floor(Math.random() * pool.length), 1)[0]);
  return scelti;
}

// Un'influenza pesata tra quelle del genere (puo' essere anche il genere stesso)
function scegliInfluenza(cat) {
  const lista = cat.influenze || [];
  if (!lista.length) return null;
  const tot = lista.reduce((a, b) => a + b.peso, 0);
  let r = Math.random() * tot;
  for (const i of lista) { r -= i.peso; if (r <= 0) return i.genere; }
  return lista[0].genere;
}

// Compone lo stile del brano dal genere: identita' fissa, strumenti del set, variante, influenza, melodia e ritmica
function componiStile(cat, variante, strumenti, influenza, guidance) {
  const direttive = ((CFG.generiOverride || {})[cat.name] || {}).direttive || [];
  const parti = [
    cat.stile,
    direttive.length ? `producer notes: ${direttive.join('; ')}` : '',
    `instruments: ${strumenti.join(', ')}`,
    variante ? variante.keywords : '',
    influenza ? `influence: ${influenza}` : '',
    cat.enfasi ? `emphasis: ${cat.enfasi}` : '',
    cat.melodia ? `melody: ${cat.melodia}` : '',
    cat.accordi ? `chords: ${cat.accordi}` : '',
    cat.ritmica ? `rhythm: ${cat.ritmica}` : '',
    (guidance.style_extra || []).join(', '),
    cat.vocale_senza_parole ? 'wordless vocals, no lyrics' : 'instrumental, no vocals',
  ].filter(Boolean);
  return parti.join(', ');
}

// Divieti del genere e quelli generali
function divietiDi(cat, guidance) {
  return [...(cat.vietati || []), ...(guidance.style_avoid || [])].join(', ');
}

// ---- Libreria iBroadcast: incollata nei nodi di caricamento (non in tutti i blocchi) ----
// Impronta FNV-1a dell'audio (senza l'header ID3): identifica i duplicati
function fnvAudio(raw) {
  let i = 0;
  if (raw.length > 10 && raw.toString('ascii', 0, 3) === 'ID3') {
    const size = ((raw[6] & 0x7f) << 21) | ((raw[7] & 0x7f) << 14) | ((raw[8] & 0x7f) << 7) | (raw[9] & 0x7f);
    i = 10 + size;
  }
  let h = 0x811c9dc5;
  for (let k = i; k < raw.length; k++) h = Math.imul(h ^ raw[k], 0x01000193) >>> 0;
  return h.toString(16) + '-' + raw.length;
}

// ---- Tag ID3v2.3 completi, scritti nel file prima del caricamento ----
function syncsafe(n) {
  return Buffer.from([(n >> 21) & 0x7f, (n >> 14) & 0x7f, (n >> 7) & 0x7f, n & 0x7f]);
}
function frame(id, payload) {
  const head = Buffer.alloc(10);
  head.write(id, 0, 'ascii');
  head.writeUInt32BE(payload.length, 4);
  return Buffer.concat([head, payload]);
}
// Testo UTF-16 con BOM (encoding 0x01 di ID3v2.3)
function utf16(s) {
  return Buffer.concat([Buffer.from([0x01, 0xff, 0xfe]), Buffer.from(String(s), 'utf16le')]);
}
function textFrame(id, value) {
  if (value === undefined || value === null || value === '') return null;
  return frame(id, utf16(value));
}
function commentFrame(text) {
  if (!text) return null;
  // encoding 0x01, lingua 'ita', descrizione vuota (BOM + terminatore), testo (BOM + UTF-16)
  const payload = Buffer.concat([Buffer.from([0x01]), Buffer.from('ita', 'ascii'), Buffer.from([0xff, 0xfe, 0x00, 0x00]), Buffer.from([0xff, 0xfe]), Buffer.from(String(text), 'utf16le')]);
  return frame('COMM', payload);
}

// Scrive i tag nel file: rimuove un eventuale header ID3 esistente e ne mette uno nuovo.
function tagFile(file, meta) {
  const raw = fs.readFileSync(file);
  let audio = raw;
  if (raw.length > 10 && raw.toString('ascii', 0, 3) === 'ID3') {
    const size = ((raw[6] & 0x7f) << 21) | ((raw[7] & 0x7f) << 14) | ((raw[8] & 0x7f) << 7) | (raw[9] & 0x7f);
    audio = raw.subarray(10 + size);
  }
  const year = String(new Date(meta.generato_il || Date.now()).getFullYear());
  const album = meta.categoria || 'Raccolta';
  const comment = [meta.descrizione, meta.attivita && `Attivita': ${meta.attivita}`, meta.style && `Stile: ${meta.style}`,
    meta.energia && `Energia: ${meta.energia}/5`, meta.struttura && `Struttura: ${meta.struttura}`, 'Strumentale, generato con YuE2']
    .filter(Boolean).join(' | ');
  const frames = [
    textFrame('TIT2', meta.titolo),
    textFrame('TPE1', CFG.artista),
    textFrame('TPE2', CFG.artista),
    textFrame('TALB', album),
    textFrame('TCON', meta.genere || meta.categoria),
    textFrame('TRCK', meta.numero_traccia),
    textFrame('TIT3', meta.tipo),
    textFrame('TBPM', meta.bpm),
    textFrame('TKEY', meta.tonalita),
    textFrame('TYER', year),
    textFrame('TENC', 'Yoga Music Factory'),
    commentFrame(comment),
    apicFrame(coverPng(meta.categoria, Number(meta.numero_traccia) || 1)),
  ].filter(Boolean);
  const body = Buffer.concat(frames);
  const header = Buffer.concat([Buffer.from('ID3'), Buffer.from([0x03, 0x00, 0x00]), syncsafe(body.length)]);
  fs.writeFileSync(file, Buffer.concat([header, body, audio]));
  return frames.length;
}

// Ambito del brano (yoga o musica), dal catalogo
function ambitoDi(meta) {
  const c = (CFG.categories || []).find((x) => x.name === meta.categoria);
  return (c && c.ambito) || 'yoga';
}

// Chiamata all'API iBroadcast tramite il gateway locale (il token resta li')
async function ibApi(access, mode, args) {
  const r = await gw('/ib/api', { mode, args });
