// Applica tag e inserisce il brano nella playlist della sua categoria
async function organizza(access, meta, trackId, state) {
  const tid = Number(trackId);
  const slug = (s) => String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
  const extra = (CFG.tag_extra && CFG.tag_extra[meta.categoria]) || [];
  const fam = ((CFG.categories || []).find((x) => x.name === meta.categoria) || {}).famiglia;
  const names = [ambitoDi(meta), fam ? `famiglia-${slug(fam)}` : null, `categoria-${slug(meta.categoria)}`, `energia-${meta.energia}`, `struttura-${slug(meta.struttura)}`, `tipo-${slug(meta.tipo)}`, ...extra.map(slug)].filter((n) => n && !n.endsWith('-undefined'));
  for (const n of names) {
    const id = await tagId(access, state, n);
    await ibApi(access, 'tagtracks', { tagid: id, tracks: [tid], untag: false });
  }
  const pid = await playlistId(access, state, meta);
  await ibApi(access, 'appendplaylist', { playlist: pid, tracks: [tid] });
}

async function upload(access, file) {
  const r = await gwUpload(path.basename(file), fs.readFileSync(file));
  const j = r.json || {};
  if (j.result === false) throw new Error('upload non accettato (HTTP ' + r.status + '): ' + (j.message || ''));
  const match = /\((.*)\) uploaded successfully/.exec(j.message || '');
  return match ? match[1] : 'ok';
}

// ---- Copertine locali: PNG generato in JavaScript, colori e forma per genere ----
// Nessun servizio esterno. Il PNG usa blocchi deflate "stored" (non compressi): semplice e valido.

const CRC_TABLE = (() => {
  const t = new Uint32Array(256);
  for (let n = 0; n < 256; n++) {
    let c = n;
    for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
    t[n] = c >>> 0;
  }
  return t;
})();
function crc32(buf) {
  let c = 0xffffffff;
  for (let i = 0; i < buf.length; i++) c = CRC_TABLE[(c ^ buf[i]) & 0xff] ^ (c >>> 8);
  return (c ^ 0xffffffff) >>> 0;
}
function adler32(buf) {
  let a = 1, b = 0;
  for (let i = 0; i < buf.length; i++) { a = (a + buf[i]) % 65521; b = (b + a) % 65521; }
  return ((b << 16) | a) >>> 0;
}
function pngChunk(type, data) {
  const len = Buffer.alloc(4); len.writeUInt32BE(data.length);
  const td = Buffer.concat([Buffer.from(type, 'ascii'), data]);
  const crc = Buffer.alloc(4); crc.writeUInt32BE(crc32(td));
  return Buffer.concat([len, td, crc]);
}
function hexRgb(h) {
  const n = parseInt(h.replace('#', ''), 16);
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
}

// Genera il PNG quadrato di dimensione size con una funzione colore(x, y) -> [r,g,b]
function makePng(size, colore) {
  const raw = Buffer.alloc(size * (size * 3 + 1));
  let p = 0;
  for (let y = 0; y < size; y++) {
    raw[p++] = 0; // filtro "nessuno"
    for (let x = 0; x < size; x++) {
      const [r, g, b] = colore(x, y);
      raw[p++] = r; raw[p++] = g; raw[p++] = b;
    }
  }
  // zlib con blocchi stored (max 65535 byte ciascuno)
  const blocchi = [];
  for (let off = 0; off < raw.length; off += 65535) {
    const fine = Math.min(raw.length, off + 65535);
    const dati = raw.subarray(off, fine);
    const ultimo = fine === raw.length ? 1 : 0;
    const h = Buffer.alloc(5);
    h[0] = ultimo;
    h.writeUInt16LE(dati.length, 1);
    h.writeUInt16LE(~dati.length & 0xffff, 3);
    blocchi.push(h, dati);
  }
  const ad = Buffer.alloc(4); ad.writeUInt32BE(adler32(raw));
  const zlib = Buffer.concat([Buffer.from([0x78, 0x01]), ...blocchi, ad]);
  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(size, 0); ihdr.writeUInt32BE(size, 4);
  ihdr[8] = 8; ihdr[9] = 2; ihdr[10] = 0; ihdr[11] = 0; ihdr[12] = 0;
  return Buffer.concat([
    Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]),
    pngChunk('IHDR', ihdr),
    pngChunk('IDAT', zlib),
    pngChunk('IEND', Buffer.alloc(0)),
  ]);
}

// Copertina astratta per genere: gradiente tra i due colori del genere, anelli e onda con il terzo colore.
// Il seme (numero del brano) varia la posizione degli anelli, cosi' ogni copertina e' diversa.
function coverPng(categoria, seme) {
  const cat = (CFG.categories || []).find((c) => c.name === categoria);
  const pal = (cat && cat.colori && cat.colori.length === 3) ? cat.colori : ['#1d3b4a', '#6fa8a0', '#f2d7a0'];
  const [c1, c2, c3] = pal.map(hexRgb);
  const size = 300;
  const cx = 60 + ((seme * 37) % 180), cy = 60 + ((seme * 53) % 180);
  const mix = (a, b, t) => a.map((v, i) => Math.round(v + (b[i] - v) * t));
  return makePng(size, (x, y) => {
    const base = mix(c1, c2, y / size);
    const d = Math.hypot(x - cx, y - cy);
    const anello = Math.abs(Math.sin(d / 18)) > 0.82;
    const onda = Math.abs(y - (size * 0.62 + Math.sin(x / 22) * 14)) < 5;
    if (onda) return mix(base, c3, 0.75);
    if (anello) return mix(base, c3, 0.35);
    return base;
  });
}

// Frame APIC (ID3v2.3): copertina anteriore in PNG
function apicFrame(png) {
  const payload = Buffer.concat([
    Buffer.from([0x00]), // testo ISO-8859-1
    Buffer.from('image/png', 'ascii'), Buffer.from([0x00]),
    Buffer.from([0x03]), // copertina anteriore
    Buffer.from([0x00]), // descrizione vuota
    png,
  ]);
  return frame('APIC', payload);
}

// BLOCCO 3d1 - Prepara caricamento: raccoglie i brani da caricare (nuovi, mancanti, da ritaggare),
// scarta i duplicati per impronta audio e scrive i tag ID3 completi nel file. Non chiama iBroadcast.
const inp = $input.first().json;
const state = inp.state;
state.uploadQueue = state.uploadQueue || [];
if (inp.outcome === 'saved' && inp.file) state.uploadQueue.push(inp.file);

// Una sola scansione: i brani senza il campo ibroadcast e quelli senza tag ID3 completi entrano in coda
const accoda = (full) => { if (!state.uploadQueue.includes(full)) state.uploadQueue.push(full); };
if (!state.ibroadcastScanned) {
  const walkLib = (dir) => {
    for (const name of fs.readdirSync(dir)) {
      const full = path.join(dir, name);
      if (name === '_scartati') continue;
      if (fs.statSync(full).isDirectory()) walkLib(full);
      else if (/\.(mp3|flac|wav|ogg)$/.test(name)) {
        const meta = readJsonSafe(full.replace(/\.[^.]+$/, '.json'), null);
        if (meta && !meta.ibroadcast) accoda(full);
      }
    }
  };
  if (fs.existsSync(CFG.root)) walkLib(CFG.root);
  state.ibroadcastScanned = true;
}
if (!state.retagScanned) {
  const walkRetag = (dir) => {
    for (const name of fs.readdirSync(dir)) {
      const full = path.join(dir, name);
      if (name === '_scartati') continue;
      if (fs.statSync(full).isDirectory()) walkRetag(full);
      else if (/\.(mp3|flac|wav|ogg)$/.test(name)) {
        const meta = readJsonSafe(full.replace(/\.[^.]+$/, '.json'), null);
        if (meta && meta.ibroadcast && !meta.id3_frames) accoda(full);
      }
    }
  };
  if (fs.existsSync(CFG.root)) walkRetag(CFG.root);
  state.retagScanned = true;
}

// Ai brani della coda: duplicati scartati, gli altri ricevono i tag ID3 pronti per il caricamento
const pending = state.uploadQueue.splice(0);
const daCaricare = [];
for (const file of pending) {
  if (!fs.existsSync(file)) continue;
  try {
    const jsonPath = file.replace(/\.[^.]+$/, '.json');
    const meta = readJsonSafe(jsonPath, {});
    const hashAudio = fnvAudio(fs.readFileSync(file));
    const gia = libraryTracks().find((t) => t.meta.hash_audio === hashAudio && t.meta.ibroadcast && t.meta.ibroadcast.track_id && t.jsonPath !== jsonPath);
    if (gia) {
      meta.hash_audio = hashAudio;
      meta.duplicato_di = gia.meta.titolo;
      fs.writeFileSync(jsonPath, JSON.stringify(meta, null, 2));
      log(`iBroadcast: ${meta.titolo} identico a ${gia.meta.titolo}, non ricaricato`);
      continue;
    }
    meta.hash_audio = hashAudio;
    const nTags = tagFile(file, meta);
    daCaricare.push({ file, jsonPath, nTags, titolo: meta.titolo, tentativi: state.uploadTries ? (state.uploadTries[file] || 0) : 0 });
  } catch (e) {
    log(`iBroadcast: preparazione di ${path.basename(file)} non riuscita: ${e.message}`);
  }
}
return [{ json: { state, outcome: inp.outcome, daCaricare } }];

