  } catch (e) { /* log non ancora creato */ }
  try {
    if (fs.statSync(CFG.errorsFile).size > 2 * 1024 * 1024) fs.renameSync(CFG.errorsFile, CFG.errorsFile + '.1');
  } catch (e) { /* file non ancora creato */ }
  fs.appendFileSync(CFG.logFile, `${ts} ${msg}\n`);
