// Chiamata al modello locale: ritorna il primo oggetto JSON presente nella risposta.
async function llmJson(system, user, maxTokens = 1200) {
  const r = await req('POST', `${CFG.llm}/chat/completions`, {
    ms: 600000,
    body: {
      model: CFG.llmModel,
      messages: [
        { role: 'system', content: system },
        { role: 'user', content: user },
      ],
      temperature: 0.8,
      max_tokens: maxTokens,
    },
  });
  if (!r.ok) throw new Error(`LLM HTTP ${r.status}`);
  const text = JSON.parse(r.buf.toString('utf8')).choices[0].message.content || '';
  const a = text.indexOf('{');
  const b = text.lastIndexOf('}');
  if (a === -1 || b === -1) throw new Error('nessun JSON nella risposta del modello');
  return JSON.parse(text.slice(a, b + 1));
}

function slugify(s) {
  return (s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase()
    .replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 60) || 'brano';
}

function uniquePath(dir, base, ext) {
  let name = base;
  let i = 2;
  while (fs.existsSync(path.join(dir, name + ext))) name = `${base}-${i++}`;
  return path.join(dir, name + ext);
}

// Cartella di un brano: radice / Yoga o Sottofondo / famiglia / categoria / tipo
function cartellaBrano(categoria, tipo) {
  const c = (CFG.categories || []).find((x) => x.name === categoria) || {};
  const ambito = c.ambito === 'yoga' ? 'Yoga' : 'Sottofondo';
  return path.join(CFG.root, ambito, c.famiglia || 'generale', categoria || 'senza-categoria', tipo || 'senza-tipo');
}

// Slot deterministico: ruota su categoria, tipo e struttura, cosi' i brani sono variati.
function slotFor(cursor, guidance = DEFAULT_GUIDANCE) {
  const n = CFG.categories.length;
  const category = CFG.categories[cursor % n];
  const round = Math.floor(cursor / n);
  const allowed = (guidance.struttura_pref && guidance.struttura_pref[category.name]) || category.strutture;
  const structure = allowed[round % allowed.length];
  const tipo = CFG.tipi[round % CFG.tipi.length];
  return { category: { ...category, bpm: bpmRangeOf(guidance, category) }, tipo, struttura: structure, sezioni: CFG.strutture[structure] };
}

// Intervallo bpm "min-max" da guidance, o il default della categoria
function bpmRangeOf(guidance, category) {
  const m = /^(\d+)\s*-\s*(\d+)$/.exec((guidance.bpm_range || {})[category.name] || '');
  return m ? [Number(m[1]), Number(m[2])] : category.bpm;
}

function clampDur(v) {
  const n = Math.round(Number(v));
  if (!Number.isFinite(n)) return CFG.durDefault;
  return Math.min(CFG.durMax, Math.max(CFG.durMin, n));
}

// Intervallo "min-max" dal suggerimento di durata per categoria (default: intero range).
function durRange(guidance, category) {
  const h = (guidance.durata_hint || {})[category];
  const m = /^(\d+)\s*-\s*(\d+)$/.exec(h || '');
  if (!m) return [CFG.durMin, CFG.durMax];
  return [clampDur(m[1]), clampDur(m[2])];
}

// Rimette in coda il concept del job corrente, o lo scarta dopo maxAttempts tentativi.
function requeue(state, reason) {
  const c = state.job.concept;
  state.job = null;
  c.attempts = (c.attempts || 0) + 1;
  if (c.attempts >= CFG.maxAttempts) {
    state.failed.push({ titolo: c.titolo, categoria: c.categoria, tipo: c.tipo, motivo: reason, at: new Date().toISOString() });
    log(`scartato "${c.titolo}" dopo ${c.attempts} tentativi: ${reason}`);
  } else {
    state.queue.unshift(c);
    log(`riaccodo "${c.titolo}" (tentativo ${c.attempts}): ${reason}`);
  }
}

// Estrae la traccia audio dalla risposta multipart del motore.
function extractAudio(buf, ct) {
  const m = /boundary="?([^";]+)"?/i.exec(ct || '');
  if (!m) return { data: buf, ext: 'mp3' };
  const sep = Buffer.from('--' + m[1]);
  const parts = [];
  let idx = buf.indexOf(sep);
  while (idx !== -1) {
    const start = idx + sep.length;
    const next = buf.indexOf(sep, start);
    parts.push(buf.subarray(start, next === -1 ? buf.length : next));
    idx = next;
  }
  for (const p of parts) {
    const hEnd = p.indexOf('\r\n\r\n');
    if (hEnd === -1) continue;
    const head = p.subarray(0, hEnd).toString('utf8').toLowerCase();
    if (!(head.includes('audio/') || head.includes('filename'))) continue;
    let data = p.subarray(hEnd + 4);
    if (data.length >= 2 && data[data.length - 2] === 13 && data[data.length - 1] === 10) data = data.subarray(0, -2);
    const ext = /flac/.test(head) ? 'flac' : /wav/.test(head) ? 'wav' : /ogg/.test(head) ? 'ogg' : 'mp3';
    return { data, ext };
  }
  throw new Error('nessuna traccia audio nella risposta');
}

// Voti utente da feedback.csv (colonne: file;voto;nota oppure file,voto,nota).
function readVotes() {
  let text = '';
  try {
    text = fs.readFileSync(CFG.feedbackFile, 'utf8');
  } catch (e) {
    return {};
  }
  const votes = {};
  for (const line of text.split(/\r?\n/).slice(1)) {
    if (!line.trim()) continue;
    const cols = line.split(line.includes(';') ? ';' : ',');
    const file = (cols[0] || '').trim();
    const voto = Number((cols[1] || '').trim());
    if (file && voto >= 1 && voto <= 5) votes[file] = { voto, nota: (cols[2] || '').trim() };
  }
  return votes;
}

// ---- Apprendimento: ricette, punteggi e scelta del brano successivo (UCB) ----
// Incollato dopo lib.js in ogni blocco. Un voto utente vale CFG.pesoVoto; i dati automatici valgono 1.
// Default, a meno che config\parametri.json (caricato in lib.js) non li sostituisca
CFG.pesoVoto = CFG.pesoVoto ?? 100;
CFG.minVotiAffidabili = CFG.minVotiAffidabili ?? 3;
CFG.maxEsperimenti = CFG.maxEsperimenti ?? 2;
CFG.durataEsperimentoBrani = CFG.durataEsperimentoBrani ?? 10;
CFG.esplorazione = CFG.esplorazione ?? 0.3;

// Tutti i brani della libreria (ogni .json con titolo)
function libraryTracks() {
  const out = [];
  const walk = (dir) => {
    for (const name of fs.readdirSync(dir)) {
      const full = path.join(dir, name);
      if (name === '_scartati') continue; // brani scartati dal controllo qualita': non fanno parte della libreria
      if (fs.statSync(full).isDirectory()) walk(full);
      else if (name.endsWith('.json') && name !== 'feedback.json') {
        const meta = readJsonSafe(full, null);
        if (meta && meta.titolo) out.push({ meta, jsonPath: full, audio: name.replace(/\.json$/, '') });
      }
    }
  };
  if (fs.existsSync(CFG.root)) walk(CFG.root);
  return out;
}

// Numero progressivo globale dei brani: non si ripete mai e non torna indietro.
// Il contatore vive in state/contatore.json e si incrementa a ogni brano salvato.
CFG.contatoreFile = path.join(CFG.dir, 'state', 'contatore.json');
function numeroProgressivo() {
  const c = readJsonSafe(CFG.contatoreFile, { prossimo: 1 });
  const numero = c.prossimo;
  fs.writeFileSync(CFG.contatoreFile, JSON.stringify({ prossimo: numero + 1, aggiornato: new Date().toISOString() }, null, 2));
  return numero;
}

// Chiave di ricetta: categoria | tipo | struttura | fascia di bpm (b0, b1, b2)
function recipeKey(categoria, tipo, struttura, band) {
  return `${categoria}|${tipo}|${struttura}|b${band}`;
}

// Sotto-intervallo bpm della fascia band (0 bassa, 1 media, 2 alta) dentro il range della categoria
function bandRange(range, band) {
  const [lo, hi] = range;
  const step = (hi - lo) / 3;
  return [Math.round(lo + step * band), Math.round(lo + step * (band + 1))];
}

// Voto utente per un brano: dal feedback.csv (prevale) o dal campo voto del json
function votoUtente(track, votes) {
  const base = track.audio;
  const v = votes[base + '.mp3'] || votes[base + '.flac'] || votes[base + '.wav'] || votes[base + '.ogg'];
  if (v) return v.voto;
  return track.meta.voto || null;
}

// Statistiche per ricetta: voti utente (peso CFG.pesoVoto) e dati automatici (peso 1)
function recipeStats(tracks, votes) {
  const stats = {};
  for (const t of tracks) {
    const k = t.meta.ricetta;
    if (!k) continue;
    const s = (stats[k] = stats[k] || { nu: 0, u: 0, na: 0, a: 0 });
    s.na++;
    if (t.meta.qualita && t.meta.qualita.esito === 'ok') s.a++;
    const v = votoUtente(t, votes);
    if (v) { s.nu++; s.u += (v - 1) / 4; } // voto 1..5 -> 0..1
  }
  return stats;
}

// Punteggio di una ricetta: media pesata con prior 0.5; UCB aggiunge esplorazione
function ricettaScore(s, totale) {
  const peso = CFG.pesoVoto;
  const numeratore = 0.5 + peso * (s ? s.u : 0) + (s ? s.a : 0);
  const denominatore = 1 + peso * (s ? s.nu : 0) + (s ? s.na : 0);
  const p = numeratore / denominatore;
  const n = (s ? s.nu * peso + s.na : 0);
  const bonus = CFG.esplorazione * Math.sqrt(Math.log(totale + 2) / (n + 1));
  return { p, score: p + bonus, affidabile: (s ? s.nu : 0) >= CFG.minVotiAffidabili };
}

// Sceglie categoria, tipo, struttura e fascia di bpm per il prossimo brano.
// Ricette non ancora affidabili entrano solo come esperimento, al massimo CFG.maxEsperimenti alla volta.
function pickSlot(state, guidance) {
  const tracks = libraryTracks();
  const votes = readVotes();
  const stats = recipeStats(tracks, votes);
  const totale = tracks.length;

  // Gli esperimenti terminano quando la ricetta diventa affidabile o dopo N brani
  state.experiments = (state.experiments || []).filter((e) => {
    const s = stats[e.key];
    const affidabile = s && s.nu >= CFG.minVotiAffidabili;
    return !affidabile && totale - e.da < CFG.durataEsperimentoBrani;
  });
  const inEsperimento = new Set(state.experiments.map((e) => e.key));
  const candidati = [];
  for (const cat of CFG.categories) {
    const strutture = (guidance.struttura_pref && guidance.struttura_pref[cat.name]) || cat.strutture;
    const range = durRangeBpm(guidance, cat);
    for (const struttura of strutture) {
      for (const tipo of CFG.tipi) {
        for (let band = 0; band < 3; band++) {
          const key = recipeKey(cat.name, tipo, struttura, band);
          const s = stats[key];
          const r = ricettaScore(s, totale);
          candidati.push({ key, cat, tipo, struttura, band, range, ...r });
        }
      }
    }
  }
  // Varieta': le categorie degli ultimi due brani non tornano subito, se esistono alternative
  const ultime = (state.recent || []).slice(-5).map((r) => r.categoria);
  const altre = candidati.filter((c) => !ultime.includes(c.cat.name));
  let pool = altre.length ? altre : candidati;
  if (CFG.comandi && CFG.comandi.produciGenere) pool = candidati; // "produci ora" ignora la varieta' recente
  // Rotazione tra i generi: prima si sceglie il genere, con peso piu' alto per quelli meno rappresentati
  // in libreria (i generi senza brani pesano di piu'). Poi si applica la logica di ricetta solo a quel genere.
  const conta = {};
  for (const t of tracks) conta[t.meta.categoria] = (conta[t.meta.categoria] || 0) + 1;
  // Peso e stato (attivo/sospeso) per genere da config\parametri.json; "produci ora" forza un genere
  const ov = (n) => CFG.generiOverride[n] || { peso: 1, attivo: true };
  const tutti = [...new Set(pool.map((c) => c.cat.name))];
  let nomi = tutti.filter((n) => ov(n).attivo);
  if (CFG.comandi && CFG.comandi.produciGenere && tutti.includes(CFG.comandi.produciGenere)) nomi = [CFG.comandi.produciGenere];
  if (!nomi.length) nomi = tutti; // tutti sospesi: la produzione non si ferma
  const pesi = nomi.map((n) => ov(n).peso / Math.pow(1 + (conta[n] || 0), 2));
  let r = Math.random() * pesi.reduce((a, b) => a + b, 0);
  let sceltaCat = nomi[nomi.length - 1];
  for (let i = 0; i < nomi.length; i++) { r -= pesi[i]; if (r <= 0) { sceltaCat = nomi[i]; break; } }
  pool = pool.filter((c) => c.cat.name === sceltaCat);
  candidati.splice(0, candidati.length, ...pool);

  // Prima le ricette affidabili con punteggio migliore; le non affidabili solo se c'e' posto negli esperimenti
  const affidabili = candidati.filter((c) => c.affidabile).sort((a, b) => b.score - a.score);
  const nuove = candidati.filter((c) => !c.affidabile).sort((a, b) => b.score - a.score);
  let scelto = null;
  const postoEsperimento = state.experiments.length < CFG.maxEsperimenti;
  if (nuove.length && (postoEsperimento || inEsperimento.has(nuove[0].key)) && Math.random() < 0.5) {
    scelto = nuove.find((c) => inEsperimento.has(c.key)) || nuove[0];
  }
  if (!scelto) scelto = affidabili[0] || nuove[0];
  if (!scelto.affidabile && !inEsperimento.has(scelto.key)) state.experiments.push({ key: scelto.key, da: totale });

  const cat = { ...scelto.cat, bpm: bandRange(scelto.range, scelto.band) };
  return {
    category: cat,
    tipo: scelto.tipo,
    struttura: scelto.struttura,
    sezioni: CFG.strutture[scelto.struttura],
    band: scelto.band,
    ricetta: scelto.key,
    esperimento: !scelto.affidabile,
    punteggio: Number(scelto.score.toFixed(3)),
  };
}

// Intervallo bpm della categoria, da guidance (come in lib.js ma usabile qui)
function durRangeBpm(guidance, cat) {
  const m = /^(\d+)\s*-\s*(\d+)$/.exec((guidance.bpm_range || {})[cat.name] || '');
  return m ? [Number(m[1]), Number(m[2])] : cat.bpm;
}

// ---- Identita' dei generi: stile composto in codice, varianti scelte con UCB sui voti ----

// Statistiche per variante di un genere (voti utente e dati automatici)
function varianteStats(tracks, votes, nomeCategoria) {
  const stats = {};
  for (const t of tracks) {
    if (t.meta.categoria !== nomeCategoria || !t.meta.variante) continue;
    const s = (stats[t.meta.variante] = stats[t.meta.variante] || { nu: 0, u: 0, na: 0, a: 0 });
    s.na++;
    if (t.meta.qualita && t.meta.qualita.esito === 'ok') s.a++;
    const v = votoUtente(t, votes);
    if (v) { s.nu++; s.u += (v - 1) / 4; }
  }
  return stats;
}

// Sceglie la variante del genere con il punteggio migliore (UCB), con un po' di esplorazione
function pickVariante(cat, tracks, votes) {
  const varianti = cat.varianti || [];
  if (!varianti.length) return null;
  const stats = varianteStats(tracks, votes, cat.name);
  const totale = tracks.filter((t) => t.meta.categoria === cat.name).length;
  const scelte = varianti.map((v) => ({ v, ...ricettaScore(stats[v.nome], totale) }));
  scelte.sort((a, b) => b.score - a.score);
  return scelte[0].v;
}

// Sottoinsieme casuale di strumenti del genere (solo quelli del suo set), 2-4 per brano
function scegliStrumenti(cat) {
  const pool = [...(cat.strumenti || [])];
  const n = Math.min(pool.length, 2 + Math.floor(Math.random() * 3));
  const scelti = [];
  while (scelti.length < n && pool.length) scelti.push(pool.splice(Math.floor(Math.random() * pool.length), 1)[0]);
  return scelti;
}

// Un'influenza pesata tra quelle del genere (puo' essere anche il genere stesso)
function scegliInfluenza(cat) {
  const lista = cat.influenze || [];
  if (!lista.length) return null;
  const tot = lista.reduce((a, b) => a + b.peso, 0);
  let r = Math.random() * tot;
  for (const i of lista) { r -= i.peso; if (r <= 0) return i.genere; }
  return lista[0].genere;
}

// Compone lo stile del brano dal genere: identita' fissa, strumenti del set, variante, influenza, melodia e ritmica
function componiStile(cat, variante, strumenti, influenza, guidance) {
  const direttive = ((CFG.generiOverride || {})[cat.name] || {}).direttive || [];
  const parti = [
    cat.stile,
    direttive.length ? `producer notes: ${direttive.join('; ')}` : '',
    `instruments: ${strumenti.join(', ')}`,
    variante ? variante.keywords : '',
    influenza ? `influence: ${influenza}` : '',
    cat.enfasi ? `emphasis: ${cat.enfasi}` : '',
    cat.melodia ? `melody: ${cat.melodia}` : '',
    cat.accordi ? `chords: ${cat.accordi}` : '',
    cat.ritmica ? `rhythm: ${cat.ritmica}` : '',
    (guidance.style_extra || []).join(', '),
    cat.vocale_senza_parole ? 'wordless vocals, no lyrics' : 'instrumental, no vocals',
  ].filter(Boolean);
  return parti.join(', ');
}

// Divieti del genere e quelli generali
function divietiDi(cat, guidance) {
  return [...(cat.vietati || []), ...(guidance.style_avoid || [])].join(', ');
}

// BLOCCO 10 - Voti da iBroadcast: legge la libreria (sola lettura, via gateway) ogni 10 minuti e converte
// i segnali che tu gia' dai nell'app in voti:
//  - valutazione a stelle (rating 1-5)  -> voto diretto
//  - tag utente (preferito, scarta, voto-N) -> voto
//  - playlist utente (preferiti, scartati) -> voto
//  - brano nel cestino -> voto 1 (se non c'e' un segnale migliore)
// Gli ascolti (plays) vengono solo registrati come dato.
const CADENZA_MS = 10 * 60 * 1000;
const VOTI_FILE = path.join(CFG.dir, 'state', 'voti-ibroadcast.json');
const ultimo = readJsonSafe(VOTI_FILE, { lastRun: 0 });
if (Date.now() - ultimo.lastRun < CADENZA_MS) return [{ json: { voti: 'non ancora' } }];
// Non scrive guidance.json mentre la pipeline e' in corso: riprova al giro successivo
if (lockOccupato('pipeline')) return [{ json: { voti: 'pipeline occupata' } }];

function decodifica(d) {
  if (!d || !d.map) return d || {};
  const out = {};
  for (const [id, riga] of Object.entries(d)) {
    if (id === 'map') continue;
    const o = {};
    for (const [k, i] of Object.entries(d.map)) o[k] = riga[i];
    out[id] = o;
  }
  return out;
}

let lib;
try {
  const r = await gw('/ib/library', {});
  lib = (r.json && r.json.library) ? r.json.library : null;
  if (!lib) throw new Error('risposta libreria vuota (HTTP ' + r.status + ')');
} catch (e) {
  log('voti iBroadcast: lettura libreria non riuscita: ' + e.message);
  return [{ json: { voti: 'errore' } }];
}

const tracce = decodifica(lib.tracks);
const playlist = Object.values(decodifica(lib.playlists));
const tag = Object.values(decodifica(lib.tags));

// Valori dai tag e dalle playlist dell'utente (non quelli creati dal sistema)
const mai = (nome) => /^(yoga|musica|famiglia-|categoria-|energia-|struttura-|tipo-|Yoga - |Musica - |Recently|Most Recent)/i.test(nome || '');
// Parole di voto e di tempo: dalla tassonomia del catalogo, valide per ogni genere
const TASS = CFG.tassonomia || { voto: { preferito: 'preferit|fav|like|top|ok', scartato: 'scart|skip|brutt|no$|delete' }, tempo: { 'piu-veloce': 'piu.?veloce', 'piu-lento': 'piu.?lento' }, passoBpm: 6, limiteBpm: 15 };
const PREF = new RegExp(TASS.voto.preferito, 'i');
const SCART = new RegExp(TASS.voto.scartato, 'i');
const VELOCE = new RegExp(TASS.tempo['piu-veloce'], 'i');
const LENTO = new RegExp(TASS.tempo['piu-lento'], 'i');
const fonteVoto = {}; // track id -> { voto, fonte }
const tempoPerTraccia = {}; // track id -> +1 (piu' veloce) | -1 (piu' lento)

for (const p of playlist) {
  if (mai(p.name)) continue;
  for (const id of (p.tracks || [])) {
    if (PREF.test(p.name)) fonteVoto[String(id)] = { voto: 5, fonte: 'playlist ' + p.name };
    else if (SCART.test(p.name)) fonteVoto[String(id)] = { voto: 1, fonte: 'playlist ' + p.name };
  }
}
for (const t of tag) {
  if (mai(t.name)) continue;
  const m = /^voto-([1-5])$/i.exec(t.name || '');
  for (const id of (t.tracks || [])) {
    if (m) fonteVoto[String(id)] = { voto: Number(m[1]), fonte: 'tag ' + t.name };
    else if (PREF.test(t.name)) fonteVoto[String(id)] = { voto: 5, fonte: 'tag ' + t.name };
    else if (SCART.test(t.name)) fonteVoto[String(id)] = { voto: 1, fonte: 'tag ' + t.name };
    // tag di tempo: indicano che il ritmo del genere va alzato o abbassato
    if (VELOCE.test(t.name)) tempoPerTraccia[String(id)] = 1;
    else if (LENTO.test(t.name)) tempoPerTraccia[String(id)] = -1;
  }
}

// Brani della libreria: i nostri (con track_id) confrontati con i segnali
const nostri = [];
(function walk(dir) {
  for (const n of fs.readdirSync(dir)) {
    const f = path.join(dir, n);
    if (n === '_scartati') continue;
    if (fs.statSync(f).isDirectory()) walk(f);
    else if (n.endsWith('.json') && n !== 'feedback.json') {
      const m = readJsonSafe(f, null);
      if (m && m.titolo && m.ibroadcast && m.ibroadcast.track_id) nostri.push({ json: f, meta: m, id: String(m.ibroadcast.track_id) });
    }
  }
})(CFG.root);

const righeCsv = (() => { try { return fs.readFileSync(CFG.feedbackFile, 'utf8').split(/\r?\n/).filter(Boolean); } catch (e) { return ['file;voto;nota']; } })();
let csvCambiato = false;
let aggiornati = 0;
let ascoltiTot = 0;
for (const b of nostri) {
  const t = tracce[b.id];
  if (!t) continue;
  const ascolti = Number(t.plays) || 0;
  ascoltiTot += ascolti;
  let voto = null, fonte = null;
  if (Number(t.rating) >= 1) { voto = Math.min(5, Math.round(Number(t.rating))); fonte = 'valutazione iBroadcast'; }
  else if (fonteVoto[b.id]) { voto = fonteVoto[b.id].voto; fonte = fonteVoto[b.id].fonte; }
  else if (t.trashed) { voto = 1; fonte = 'cestino iBroadcast'; }

  b.meta.ascolti = ascolti;
  b.meta.ibroadcast.ascolti = ascolti;

  // Tag di tempo: sposta il bpm del genere di un passo, una sola volta per brano, entro i limiti
  const dir = tempoPerTraccia[b.id];
  const giaApplicati = ultimo.tempoApplicati || [];
  if (dir && !giaApplicati.includes(b.id)) {
    const c = (CFG.categories || []).find((x) => x.name === b.meta.categoria);
    if (c) {
      const g = readGuidance();
      const attuale = (g.bpm_range || {})[c.name] ? g.bpm_range[c.name].split('-').map(Number) : c.bpm.slice();
      const minimo = c.bpm[0] - TASS.limiteBpm, massimo = c.bpm[1] + TASS.limiteBpm;
      const lo = Math.max(minimo, Math.min(massimo, attuale[0] + dir * TASS.passoBpm));
      const hi = Math.max(minimo, Math.min(massimo, attuale[1] + dir * TASS.passoBpm));
      if (lo < hi) {
        const prossima = { ...g, versione: g.versione + 1, aggiornato: new Date().toISOString(), bpm_range: { ...(g.bpm_range || {}), [c.name]: `${lo}-${hi}` }, note: `bpm di ${c.name} ${dir > 0 ? 'alzato' : 'abbassato'} da un tag di tempo` };
        fs.mkdirSync(CFG.historyDir, { recursive: true });
        fs.writeFileSync(path.join(CFG.historyDir, `guidance-v${g.versione}.json`), JSON.stringify(g, null, 2));
        fs.writeFileSync(CFG.guidanceFile, JSON.stringify(prossima, null, 2));
        log(`voti iBroadcast: tempo di ${c.name} ${dir > 0 ? 'alzato' : 'abbassato'} a ${lo}-${hi} bpm (versione ${prossima.versione})`);
      }
    }
    giaApplicati.push(b.id);
    ultimo.tempoApplicati = giaApplicati.slice(-500);
  }
  if (voto !== null && b.meta.voto !== voto) {
    b.meta.voto = voto;
    b.meta.voto_fonte = fonte;
    // il voto va anche in feedback.csv, che il sistema legge per apprendere
    const audio = path.basename(b.json).replace(/\.json$/, '') + '.mp3';
    const idx = righeCsv.findIndex((r) => r.split(';')[0] === audio);
    const nota = idx > 0 ? (righeCsv[idx].split(';')[2] || '') : '';
    if (idx > 0) righeCsv[idx] = `${audio};${voto};${nota}`;
    else righeCsv.push(`${audio};${voto};${fonte}`);
    csvCambiato = true;
    aggiornati++;
  }
  fs.writeFileSync(b.json, JSON.stringify(b.meta, null, 2));
}
if (csvCambiato) fs.writeFileSync(CFG.feedbackFile, righeCsv.join('\n') + '\n');
fs.writeFileSync(VOTI_FILE, JSON.stringify({ lastRun: Date.now(), tempoApplicati: ultimo.tempoApplicati || [], ultimoEsito: { aggiornati, ascoltiTot } }, null, 2));
if (aggiornati) log(`voti iBroadcast: ${aggiornati} brani aggiornati dai segnali dell'app`);
return [{ json: { voti: 'ok', aggiornati, ascoltiTot } }];

